<div class="sm-page-head">
  <div>
    <h1 class="sm-page-title">Tasks</h1>
  </div>
  <div class="sm-page-actions"><button class="btn btn-sm-navy" onclick="document.getElementById('taskForm').scrollIntoView({behavior:'smooth'})">+ Add Task</button></div>
</div>
<div class="sm-card mb-4"><div class="sm-card-body"><form method="post" action="<?= e(url('student/tasks')) ?>" id="taskForm" novalidate><?= csrf_input() ?>
  <div class="row g-3"><div class="col-md-4"><label class="form-label" for="title">Title</label><input type="text" name="title" id="title" class="form-control" required></div><div class="col-md-3"><label class="form-label" for="subject">Subject</label><input type="text" name="subject" id="subject" class="form-control" placeholder="Subject"></div><div class="col-md-3"><label class="form-label" for="due_date">Due Date</label><input type="date" name="due_date" id="due_date" class="form-control"></div><div class="col-md-2"><label class="form-label" for="priority">Priority</label><select name="priority" id="priority" class="form-select"><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option></select></div><div class="col-12 d-flex align-items-end justify-content-end"><button type="submit" class="btn btn-sm-navy">Add Task</button></div></div></form></div></div>
<div class="sm-card"><div class="sm-card-header">Your Tasks</div><div class="sm-card-body">
  <div class="table-wrap"><table class="table table-hover align-middle mb-0">
    <thead><tr><th>Title</th><th>Subject</th><th>Priority</th><th>Due Date</th><th>Status</th><th class="text-end">Actions</th></tr></thead>
    <tbody><?php foreach ($tasks ?? [] as $t): ?><tr><td><?= e($t['title']) ?></td><td><?= e($t['subject'] ?? '-') ?></td><td><span class="badge bg-<?= $t['priority'] === 'high' ? 'danger' : ($t['priority'] === 'medium' ? 'warning' : 'info') ?>"><?= e(ucfirst($t['priority'])) ?></span></td><td><?= e($t['due_date'] ? date('M j, Y', strtotime($t['due_date'])) : '-') ?></td><td><span class="badge bg-<?= $t['status'] === 'completed' ? 'success' : 'warning' ?>"><?= e(ucfirst($t['status'])) ?></span></td><td class="text-end"><form method="post" action="<?= e(url('student/tasks/' . $t['id'] . '/delete')) ?>" style="display:inline;" data-confirm="Delete the task “<?= e($t['title']) ?>”? This cannot be undone." data-confirm-title="Delete task" data-confirm-label="Delete task" data-confirm-tone="danger"><?= csrf_input() ?><button type="submit" class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach; ?><?php if (empty($tasks)): ?><tr><td colspan="6" class="text-center text-muted py-4">No tasks found.</td></tr><?php endif; ?></tbody></table></div></div></div>